import sys

def compute_overlap(t):
    n = len(t)
    fail = [0] * n
    for i in range(1, n):
        j = fail[i-1]
        while j > 0 and t[i] != t[j]:
            j = fail[j-1]
        if t[i] == t[j]:
            j += 1
        fail[i] = j
    return fail[-1]

def max_occurrences(s, t):
    n = len(s)
    m = len(t)
    if m == 0:
        return 0
    count = 0
    i = 0
    while i <= n - m:
        if s.startswith(t, i):
            count += 1
            i += 1
        else:
            i += 1
    return count

def main():
