def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    A = list(map(int, input[idx:idx+N]))
    idx += N
    B = list(map(int, input[idx:idx+N]))
    idx += N

    if B != A:
        # Try shifting B by 1 position
        shifted = B[1:] + [B[0]]
        print("Yes")
        print(' '.join(map(str, shifted)))
    else:
        # Check if all elements are the same
        all_same = True
        for x in B:
            if x != B[0]:
                all_same = False
                break
        if all_same:
            print("Yes")
            print(' '.join(map(str, B)))
        else:
            # Try to find a derangement by swapping
            found = False
            for i in range(N-1):
                if B[i] != B[i+1]:
                    B[i], B[i+1] = B[i+1], B[i]
                    found = True
                    break
            if not found:
                print("No")
            else:
                valid = True
                for i in range(N):
                    if B[i] == A[i]:
                        valid = False
                        break
                if valid:
                    print("Yes")
                    print(' '.join(map(str, B)))
                else:
                    print("No")

if __name__ == "__main__":
    main()
